"""Operator CLI: serve | check-config | trust-host | bootstrap."""

from __future__ import annotations

import argparse
import asyncio
import logging
import re
import sys
from pathlib import Path
from typing import Any

from vps_mcp.backends.validators import VALIDATOR_BINARIES

SUDOERS_TEMPLATE = """\
# /etc/sudoers.d/vps-mcp — generated by `vps-mcp bootstrap --print-sudoers`
#
# Review before installing, then:
#   sudo install -m 0440 vps-mcp.sudoers /etc/sudoers.d/vps-mcp && sudo visudo -c
#
# NOTE: access to the container runtime and to the package manager is root-equivalent by
# nature. This file narrows *which programs* vps-mcp can run; the vps-mcp server itself
# only ever runs fixed command templates (no arbitrary commands, FR-032).

Defaults:{user} env_keep += "DEBIAN_FRONTEND"
Defaults:{user} !requiretty

Cmnd_Alias VPSMCP_SYSTEMD = /usr/bin/systemctl, /bin/systemctl, /usr/bin/journalctl, /bin/journalctl
Cmnd_Alias VPSMCP_PKG = {pkg}
Cmnd_Alias VPSMCP_FILES = /usr/bin/install, /bin/cat, /usr/bin/cat, /bin/rm, /usr/bin/rm
{runtime_alias}{validator_alias}
{user} ALL=(root) NOPASSWD: VPSMCP_SYSTEMD, VPSMCP_PKG, VPSMCP_FILES{extra}
"""

PKG_BINARIES = {
    "apt": "/usr/bin/apt-get",
    "dnf": "/usr/bin/dnf",
}
VALIDATOR_PATHS = {
    "nginx": "/usr/sbin/nginx",
    "sshd": "/usr/sbin/sshd",
    "caddy": "/usr/bin/caddy",
    "haproxy": "/usr/sbin/haproxy",
}


def render_sudoers(user: str, runtime: str, pm: str) -> str:
    runtime_alias = ""
    extra = ""
    if runtime in ("docker", "podman"):
        runtime_alias = f"Cmnd_Alias VPSMCP_RUNTIME = /usr/bin/{runtime}\n"
        extra += ", VPSMCP_RUNTIME"
    validators = ", ".join(VALIDATOR_PATHS[k] for k in VALIDATOR_BINARIES)
    validator_alias = f"Cmnd_Alias VPSMCP_VALIDATE = {validators}\n"
    extra += ", VPSMCP_VALIDATE"
    return SUDOERS_TEMPLATE.format(
        user=user,
        pkg=PKG_BINARIES[pm],
        runtime_alias=runtime_alias,
        validator_alias=validator_alias,
        extra=extra,
    )


def _cmd_serve(args: argparse.Namespace) -> int:
    from vps_mcp.config.loader import ConfigError
    from vps_mcp.server import build_server

    logging.basicConfig(
        stream=sys.stderr,
        level=getattr(logging, args.log_level),
        format="%(asctime)s %(levelname)s %(name)s: %(message)s",
    )
    try:
        server = build_server(args.config)
    except ConfigError as exc:
        for e in exc.errors:
            print(f"config error: {e}", file=sys.stderr)
        return 1
    server.run("stdio")
    return 0


def _cmd_check_config(args: argparse.Namespace) -> int:
    from vps_mcp.config.loader import ConfigError, load_config

    try:
        cfg = load_config(args.config)
    except ConfigError as exc:
        for e in exc.errors:
            print(f"ERROR {e}")
        return 1
    print(
        f"OK: vps '{cfg.vps.name}' ({cfg.vps.host}), {len(cfg.service)} declared service(s), "
        f"read_only={cfg.policy.read_only}"
    )
    if cfg.memory.enabled and cfg.memory.store:
        for line in memory_report(Path(cfg.memory.store)):
            print(line)
        from vps_mcp.config.loader import legacy_memory_folder

        legacy = (
            Path(cfg.memory.path) if cfg.memory.path else legacy_memory_folder(Path(args.config))
        )
        if (legacy / "notes").is_dir() and any((legacy / "notes").glob("*.md")):
            print(
                f"NOTE feature-004 memory notes found in {legacy}; import them with: "
                f"agent-memory migrate-004 {legacy} --project vps-{cfg.vps.name} "
                f"--environment {cfg.vps.name} --apply"
            )
    else:
        print("memory: disabled")
    return 0


PUBLIC_GIT_HOSTS = ("github.com", "gitlab.com", "bitbucket.org")


def memory_report(path: Path) -> list[str]:
    """``check-config`` lines for the memory folder: location, note count, privacy warnings."""
    import subprocess

    home = str(Path.home())
    shown = "~" + str(path)[len(home) :] if str(path).startswith(home + "/") else str(path)
    count = sum(1 for _ in (path / "memories").rglob("*.md")) if (path / "memories").is_dir() else 0
    out = [f"memory: {shown} ({count} memories)" if path.exists() else f"memory: {shown} (new)"]
    if path.exists() and path.stat().st_mode & 0o077:
        out.append(f"WARNING memory folder {shown} is readable by other users; chmod 700 it")
    probe = path if path.exists() else path.parent
    try:
        remotes = subprocess.run(  # noqa: S603 - fixed argv, no shell
            ["git", "-C", str(probe), "remote", "-v"],  # noqa: S607
            capture_output=True,
            text=True,
            timeout=5,
            check=False,
        ).stdout
    except (OSError, subprocess.SubprocessError):
        remotes = ""
    if any(h in remotes for h in PUBLIC_GIT_HOSTS):
        out.append(
            f"WARNING memory folder {shown} is inside a git repository with a hosted remote; "
            "make sure that repository is private"
        )
    return out


def _host_pattern(host: str, port: int) -> str:
    return host if port == 22 else f"[{host}]:{port}"


async def _fetch_host_key(host: str, port: int):  # type: ignore[no-untyped-def]
    import asyncssh

    return await asyncssh.get_server_host_key(host, port)


def _cmd_trust_host(args: argparse.Namespace) -> int:
    kh = Path(args.known_hosts).expanduser()
    try:
        key = asyncio.run(_fetch_host_key(args.host, args.port))
    except Exception as exc:  # noqa: BLE001
        print(f"could not fetch host key from {args.host}:{args.port}: {exc}", file=sys.stderr)
        return 1
    if key is None:
        print("server presented no host key", file=sys.stderr)
        return 1
    pattern = _host_pattern(args.host, args.port)
    line = f"{pattern} {key.export_public_key('openssh').decode().strip()}"
    print(f"Host key for {pattern}: {key.get_algorithm()} {key.get_fingerprint('sha256')}")

    existing = kh.read_text().splitlines() if kh.exists() else []
    same_host = [x for x in existing if x.split() and pattern in x.split()[0].split(",")]
    if line in existing:
        print("already pinned")
        return 0
    if same_host and not args.replace:
        print(
            f"{kh} already pins a DIFFERENT key for {pattern}. If the server was rebuilt on "
            "purpose, rerun with --replace; otherwise this may be an attack.",
            file=sys.stderr,
        )
        return 2
    if not args.yes:
        answer = input("Verify this fingerprint out-of-band. Pin it? [yes/NO] ")
        if answer.strip().lower() != "yes":
            print("not pinned")
            return 1
    kept = [x for x in existing if x not in same_host]
    kh.parent.mkdir(parents=True, exist_ok=True, mode=0o700)
    kh.write_text("\n".join([*kept, line]) + "\n")
    kh.chmod(0o600)
    print(f"pinned in {kh}")
    return 0


MIGRATION_SUDOERS = """
# --- database migration feature (vps-mcp bootstrap --with-migration) ---
# psql/createdb/dropdb as postgres and systemd-run as root are superuser/root-equivalent;
# vps-mcp only issues generated, fingerprinted commands (see README, "Migration analysis").
Defaults:{user} env_keep += "PGOPTIONS"
Cmnd_Alias VPSMCP_PG = /usr/bin/psql, /usr/bin/createdb, /usr/bin/dropdb, /usr/bin/pg_dump, \\
                       /usr/bin/pg_restore
Cmnd_Alias VPSMCP_REHEARSE = /usr/bin/systemd-run, /usr/bin/grep, /usr/bin/sha256sum, \\
                             /usr/bin/tee, /usr/bin/tail, /usr/bin/ls
{user} ALL=(postgres) NOPASSWD: VPSMCP_PG
{user} ALL=(root) NOPASSWD: VPSMCP_REHEARSE
"""

MIGRATION_SQL = """\
-- vps-mcp: read-only analysis role (peer auth maps the OS user {user} to this role).
-- Run as: sudo -u postgres psql -p <port> -f vps-mcp-migration.sql
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = '{user}') THEN
    CREATE ROLE {user} LOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE;
  END IF;
END
$$;
GRANT pg_read_all_data, pg_read_all_stats TO {user};
"""


JOBS_SUDOERS = """
# --- declared jobs (vps-mcp bootstrap --with-jobs): stat for script owner/mode checks ---
Cmnd_Alias VPSMCP_JOBS = /usr/bin/stat
{user} ALL=(root) NOPASSWD: VPSMCP_JOBS
"""


GITLAB_SUDOERS = """
# --- GitLab deploys (vps-mcp bootstrap --with-gitlab) ---
# Root-equivalent like the rest of this file: vps-mcp only ever issues its own validated argv
# (paths under /var/lib/vps-mcp/deploys and the declared destinations).
Cmnd_Alias VPSMCP_DEPLOY = /usr/bin/tar, /usr/bin/mkdir, /usr/bin/ln, /usr/bin/mv, \\
    /usr/bin/chown, /usr/bin/chmod, /usr/bin/rm, /usr/bin/readlink, /usr/bin/sha256sum, \\
    /usr/bin/cat, /usr/bin/df, /usr/bin/find, /usr/bin/curl
{user} ALL=(root) NOPASSWD: VPSMCP_DEPLOY
"""


def migration_sudoers(user: str, check_runners: list[tuple[str, str]]) -> str:
    out = MIGRATION_SUDOERS.format(user=user)
    for run_as, interpreter in sorted(set(check_runners)):
        out += f"{user} ALL=({run_as}) NOPASSWD: {interpreter}\n"
    return out


def _cmd_bootstrap(args: argparse.Namespace) -> int:
    if args.print_migration_sql:
        if not re.fullmatch(r"[a-z_][a-z0-9_]{0,31}", args.user):
            print("invalid --user", file=sys.stderr)
            return 2
        sys.stdout.write(MIGRATION_SQL.format(user=args.user))
        return 0
    if not args.print_sudoers:
        print("nothing to do; use --print-sudoers or --print-migration-sql", file=sys.stderr)
        return 2
    sys.stdout.write(render_sudoers(args.user, args.runtime, args.pm))
    if args.with_migration:
        runners: list[tuple[str, str]] = []
        if args.config:
            from vps_mcp.config.loader import ConfigError, load_config

            try:
                cfg = load_config(args.config)
            except ConfigError as exc:
                for e in exc.errors:
                    print(f"config error: {e}", file=sys.stderr)
                return 1
            if cfg.migration:
                runners = [
                    (c.run_as, c.command[0])
                    for c in cfg.migration.check
                    if c.run_as not in ("vpsmcp",)
                ]
        sys.stdout.write(migration_sudoers(args.user, runners))
    if args.with_jobs:
        sys.stdout.write(JOBS_SUDOERS.format(user=args.user))
    if args.with_gitlab:
        sys.stdout.write(GITLAB_SUDOERS.format(user=args.user))
    return 0


def _cmd_gitlab_check(args: argparse.Namespace) -> int:
    from vps_mcp.config.loader import ConfigError, load_config

    try:
        cfg = load_config(args.config)
    except ConfigError as exc:
        for e in exc.errors:
            print(f"ERROR {e}")
        return 1
    if cfg.gitlab is None:
        print("ERROR no [gitlab] section in the config")
        return 1
    return asyncio.run(_gitlab_check(cfg, with_vps=not args.no_vps))


async def _gitlab_check(cfg: Any, *, with_vps: bool, **build: Any) -> int:
    from vps_mcp.gitlab.check import report
    from vps_mcp.server import build_context

    app = build_context(cfg, **build)
    try:
        lines, ok = await report(app.gitlab, with_vps=with_vps)
    finally:
        await app.gitlab.client.aclose()
    for line in lines:
        print(line)
    return 0 if ok else 1


def build_parser() -> argparse.ArgumentParser:
    p = argparse.ArgumentParser(prog="vps-mcp", description="MCP server for VPS service management")
    sub = p.add_subparsers(dest="command", required=True)

    s = sub.add_parser("serve", help="run the MCP server on stdio")
    s.add_argument("--config", required=True)
    s.add_argument("--log-level", default="INFO", choices=["DEBUG", "INFO", "WARNING", "ERROR"])
    s.set_defaults(func=_cmd_serve)

    c = sub.add_parser("check-config", help="validate the policy file")
    c.add_argument("--config", required=True)
    c.set_defaults(func=_cmd_check_config)

    t = sub.add_parser("trust-host", help="pin the VPS host key in a known_hosts file")
    t.add_argument("--host", required=True)
    t.add_argument("--port", type=int, default=22)
    t.add_argument("--known-hosts", required=True)
    t.add_argument("--replace", action="store_true", help="replace a different pinned key")
    t.add_argument("--yes", action="store_true", help="do not prompt")
    t.set_defaults(func=_cmd_trust_host)

    b = sub.add_parser("bootstrap", help="print setup material for the VPS")
    b.add_argument("--print-sudoers", action="store_true")
    b.add_argument("--user", default="vpsmcp")
    b.add_argument("--runtime", default="docker", choices=["docker", "podman", "none"])
    b.add_argument("--pm", default="apt", choices=["apt", "dnf"])
    b.add_argument(
        "--with-migration", action="store_true", help="append the database-migration sudoers rules"
    )
    b.add_argument(
        "--with-jobs",
        action="store_true",
        help="with --with-migration: append the declared-jobs sudoers rule (stat)",
    )
    b.add_argument(
        "--print-migration-sql",
        action="store_true",
        help="print SQL creating the read-only analysis role",
    )
    b.add_argument(
        "--with-gitlab", action="store_true", help="append the GitLab deploy sudoers rules"
    )
    b.add_argument("--config", help="policy file (adds sudoers rules for declared checks)")
    b.set_defaults(func=_cmd_bootstrap)

    g = sub.add_parser("gitlab-check", help="check the GitLab token, scopes and projects")
    g.add_argument("--config", required=True)
    g.add_argument("--no-vps", action="store_true", help="skip reading deploy state on the VPS")
    g.set_defaults(func=_cmd_gitlab_check)
    return p


def main(argv: list[str] | None = None) -> int:
    args = build_parser().parse_args(argv)
    return int(args.func(args))
